PREFIX brick: <http://brickschema.org/schema/1.3/brick#>
PREFIX ref: <http://w3.org/ns/ldp>
SELECT ?label ?uri ?tsid ?unit WHERE {
  ?uri brick:hasLabel ?label .
  FILTER(?label IN ("Perimeter_mid_ZN_3","DataCenter_top_ZN_6"))
  OPTIONAL { ?uri ref:hasExternalReference ?ref ; ref:hasTimeseriesId ?tsid }
  OPTIONAL { ?uri brick:hasUnits ?unit }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
prefix brick: <https://brickschema.org/schema/Brick#>
SELECT ?uri ?label ?type WHERE {
  ?uri rdfs:label ?label .
  FILTER(CONTAINS(?label, "ZN_3") || CONTAINS(?label, "ZN_6"))
  OPTIONAL { ?uri a ?type }
}

